"""Solve the dynamic admin-tool CTF challenge.

Strategy (no hardcoded credentials):
  1. If Go source file(s) exist under /app, parse them for the XOR key and
     the encrypted byte arrays (robust to renamed variables/spacing), decode
     with the key (brute-forcing all 256 single-byte keys as a fallback, plus
     repeating-key support), and collect candidate (username, password) pairs.
  2. Otherwise (or additionally) analyze the binary itself: disassemble
     main.main for referenced string blobs / immediates, brute-force XOR over
     those blobs, and collect candidates.
  3. Try each candidate pair against the live binary until authentication
     succeeds and /app/output.txt is (re)generated.
"""

import glob
import os
import re
import struct
import subprocess
import sys

BINARY = "/app/admin-tool"
OUTPUT = "/app/output.txt"

SUCCESS_MARKERS = (
    b"Access granted",
    b"Authentication successful",
    b"Output generated",
)


# --------------------------------------------------------------------------
# helpers
# --------------------------------------------------------------------------

def find_go_sources():
    """Locate candidate Go sources (tolerates odd spacing in filenames)."""
    cands = []
    for pat in ("/app/main.go", "/app/main *.go", "/app/*.go"):
        for p in glob.glob(pat):
            if os.path.isfile(p) and p not in cands:
                cands.append(p)
    # last resort: any .go file directly under /app (handles stray spaces)
    try:
        for name in os.listdir("/app"):
            if name.strip().endswith(".go"):
                p = os.path.join("/app", name)
                if os.path.isfile(p) and p not in cands:
                    cands.append(p)
    except OSError:
        pass
    return cands


def looks_printable(bs):
    return len(bs) > 0 and all(32 <= b < 127 for b in bs)


def looks_like_credential(bs):
    """Plausible username/password bytes: printable, sane length."""
    if not (3 <= len(bs) <= 64):
        return False
    if not looks_printable(bs):
        return False
    # most credentials are word-ish; require at least 3 alphanumerics
    alnum = sum(1 for b in bs if chr(b).isalnum())
    return alnum >= 3


def credential_score(bs):
    """Higher = more credential-like (used to order trials)."""
    score = 0
    if all(chr(b).isalnum() or chr(b) in "_-!@#$%^&*+=." for b in bs):
        score += 3
    if 4 <= len(bs) <= 32:
        score += 2
    if any(chr(b).isalpha() for b in bs) and any(
        chr(b).isdigit() for b in bs
    ):
        score += 1
    return score


def parse_int_token(tok):
    tok = tok.strip()
    if not tok:
        return None
    # char literal 'a' / 'ab' (take first byte)
    if len(tok) >= 3 and tok[0] == "'" and tok[-1] == "'":
        inner = tok[1:-1].encode("utf-8", "ignore").decode(
            "unicode_escape", "ignore"
        )
        if inner:
            return ord(inner[0]) & 0xFF
        return None
    # byte('a') / uint8('a') / int('a')
    m = re.match(r"(?:byte|uint8|int|rune)\(\s*'(.)'\s*\)$", tok)
    if m:
        return ord(m.group(1)) & 0xFF
    try:
        return int(tok, 0) & 0xFF
    except ValueError:
        return None


# --------------------------------------------------------------------------
# Go source analysis
# --------------------------------------------------------------------------

def extract_arrays(text):
    """Return list of (varname_or_None, [byte ints])."""
    arrays = []
    # []byte{...} / [...]byte{...} / []uint8{...} with optional var name
    pat = re.compile(
        r"(?:var\s+)?(\w+)?\s*(?::=|=)?\s*\[\](?:byte|uint8)\s*\{([^}]*)\}",
        re.DOTALL,
    )
    for m in pat.finditer(text):
        name = m.group(1)
        body = m.group(2)
        if name in ("byte", "uint8", "var"):
            name = None
        vals = []
        for tok in body.split(","):
            tok = tok.strip()
            if not tok or tok.startswith("//"):
                continue
            tok = re.sub(r"//.*$", "", tok).strip()
            v = parse_int_token(tok)
            if v is None:
                vals = None
                break
            vals.append(v)
        if vals and 3 <= len(vals) <= 256:
            arrays.append((name, vals))
    return arrays


def extract_key_candidates(text):
    """Return list of single-byte int keys (best guess first)."""
    scored = {}

    def add(key, score):
        key &= 0xFF
        scored[key] = max(scored.get(key, -1), score)

    # identifiers used with ^ are very likely the key
    xor_operands = set()
    for m in re.finditer(r"(\w+)\s*\^", text):
        xor_operands.add(m.group(1))
    for m in re.finditer(r"\^\s*(\w+)", text):
        xor_operands.add(m.group(1))

    # assignments of integer literals: NAME := 0xAB / var NAME byte = 12
    for m in re.finditer(
        r"(?:var\s+)?(\w+)\s*(?::=|=)\s*(?:byte\s*\(\s*)?"
        r"(0[xX][0-9a-fA-F]+|0[oO][0-7]+|\d+)(?:\s*\))?",
        text,
    ):
        name, raw = m.group(1), m.group(2)
        try:
            val = int(raw, 0) & 0xFF
        except ValueError:
            continue
        score = 0
        if re.search(r"key|xor|mask|secret|cipher|seed|^k$",
                     name, re.IGNORECASE):
            score += 2
        if name in xor_operands:
            score += 4
        # byte-sized literal assigned near array definitions
        add(val, score)

    # literal XOR: `^ 0xAB` / `^ 66`
    for m in re.finditer(r"\^\s*(0[xX][0-9a-fA-F]+|\d{1,3})\b", text):
        try:
            add(int(m.group(1), 0), 5)
        except ValueError:
            pass
    # ordered: score desc, then insertion order
    return sorted(scored, key=lambda k: -scored[k])


def extract_string_keys(text):
    """Possible multi-byte (repeating) keys: short string literals."""
    keys = []
    for m in re.finditer(r'(?:var\s+)?(\w+)\s*(?::=|=)\s*"((?:[^"\\\n]|\\.)*)"',
                         text):
        name, lit = m.group(1), m.group(2)
        try:
            raw = lit.encode("utf-8").decode("unicode_escape").encode(
                "latin1")
        except Exception:
            continue
        if not (1 <= len(raw) <= 32):
            continue
        if re.search(r"key|xor|mask|secret|cipher", name, re.IGNORECASE):
            keys.insert(0, bytes(raw))
        elif name and re.search(re.escape(name) + r"\s*[\^\%\-]",
                                text):
            keys.append(bytes(raw))
    # de-dupe, keep order
    seen, out = set(), []
    for k in keys:
        if k not in seen:
            seen.add(k)
            out.append(k)
    return out


def decode_single_xor(arr, key):
    return bytes(b ^ (key & 0xFF) for b in arr)


def decode_repeating_xor(arr, key):
    return bytes(b ^ key[i % len(key)] for i, b in enumerate(arr))


def extract_plaintext_literals(text):
    """String literals that may hold plaintext credentials."""
    lits = []
    for m in re.finditer(r'"((?:[^"\\\n]|\\.){3,64})"', text):
        try:
            raw = m.group(1).encode("utf-8").decode(
                "unicode_escape").encode("latin1")
        except Exception:
            continue
        if not looks_like_credential(raw):
            continue
        low = bytes(raw).lower()
        if any(b in low for b in (b"/app", b".txt", b"usage",
                                  b"admin-tool", b"flag")):
            continue
        if b"%s" in raw or b"%q" in raw or b"\n" in raw:
            continue
        if b" " in raw and len(raw) > 24:
            continue
        lits.append(bytes(raw))
    # de-dupe, keep order
    seen, out = set(), []
    for lit in lits:
        if lit not in seen:
            seen.add(lit)
            out.append(lit)
    return out


def source_candidate_pairs(text):
    """Build ordered (user, pass) candidate pairs from Go source."""
    arrays = extract_arrays(text)
    key_cands = extract_key_candidates(text)
    str_keys = extract_string_keys(text)
    decoded = {}  # bytes -> (score, keydesc)
    for _name, arr in arrays:
        tried = set()
        for kb in key_cands:
            if kb in tried:
                continue
            tried.add(kb)
            dec = decode_single_xor(arr, kb)
            if looks_like_credential(dec):
                prev = decoded.get(dec)
                s = credential_score(dec) + 2
                if prev is None or s > prev[0]:
                    decoded[dec] = (s, "xor0x%02x" % kb)
        # exhaustive fallback: every possible single-byte key
        for kb in range(256):
            if kb in tried:
                continue
            dec = decode_single_xor(arr, kb)
            if looks_like_credential(dec):
                s = credential_score(dec)
                prev = decoded.get(dec)
                if prev is None or s > prev[0]:
                    decoded[dec] = (s, "xor0x%02x" % kb)
        for sk in str_keys:
            dec = decode_repeating_xor(arr, sk)
            if looks_like_credential(dec):
                s = credential_score(dec) + 1
                prev = decoded.get(dec)
                if prev is None or s > prev[0]:
                    decoded[dec] = (s, "repkey")
    # map arrays to roles by variable name when possible
    users, passes = [], []
    for name, arr in arrays:
        decs = []
        for dec in decoded:
            decs.append(dec)
        lname = (name or "").lower()
        is_user = any(w in lname for w in ("user", "name", "login"))
        is_pass = any(w in lname for w in ("pass", "pwd", "secret"))
        for dec in decs:
            # only attribute decodes that came from this array
            arrset = {
                decode_single_xor(arr, k) for k in list(key_cands)[:8]
            } | {decode_single_xor(arr, k) for k in range(256)}
            if dec in arrset:
                if is_user and not is_pass:
                    if dec not in users:
                        users.append(dec)
                elif is_pass and not is_user:
                    if dec not in passes:
                        passes.append(dec)
    ordered = sorted(decoded, key=lambda d: -decoded[d][0])
    pairs = []
    if users and passes:
        for u in users:
            for p in passes:
                if u != p:
                    pairs.append((u, p))
    # generic: every ordered pair of distinct decodes (best first)
    for i, u in enumerate(ordered):
        for j, p in enumerate(ordered):
            if i != j and (u, p) not in pairs:
                pairs.append((u, p))
    if len(ordered) == 1:
        # single blob might be "user:pass" style; still try it both ways
        pairs.append((ordered[0], ordered[0]))
    # plaintext literals as extra single candidates
    for lit in extract_plaintext_literals(text):
        if lit not in ordered:
            ordered.append(lit)
    for i, u in enumerate(ordered):
        for j, p in enumerate(ordered):
            if i != j and (u, p) not in pairs:
                pairs.append((u, p))
    return pairs


# --------------------------------------------------------------------------
# Binary analysis (fallback / complement)
# --------------------------------------------------------------------------

def read_file_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def elf_vaddr_to_bytes(data):
    """Parse ELF program headers; return resolver vaddr->bytes via PT_LOAD."""
    segs = []
    try:
        if data[:4] != b"\x7fELF" or data[4] != 2:  # 64-bit only
            return None
        phoff = struct.unpack("<Q", data[0x20:0x28])[0]
        phentsize = struct.unpack("<H", data[0x36:0x38])[0]
        phnum = struct.unpack("<H", data[0x38:0x3A])[0]
        for i in range(phnum):
            off = phoff + i * phentsize
            p_type, p_flags, p_offset, p_vaddr = struct.unpack(
                "<IIQQ", data[off:off + 32])
            p_filesz = struct.unpack("<Q", data[off + 32:off + 40])[0]
            p_memsz = struct.unpack("<Q", data[off + 40:off + 48])[0]
            if p_type == 1:  # PT_LOAD
                segs.append((p_vaddr, p_memsz, p_offset, p_filesz))
    except Exception:
        return None

    def resolve(vaddr, length):
        for v, memsz, foff, filesz in segs:
            if v <= vaddr and vaddr + length <= v + filesz:
                start = foff + (vaddr - v)
                return data[start:start + length]
        return None

    return resolve


def objdump_main(data_path):
    try:
        out = subprocess.run(
            ["objdump", "-d", data_path],
            capture_output=True, timeout=120).stdout.decode(
                "utf-8", "ignore")
    except Exception:
        return ""
    start = out.find("<main.main>:")
    if start < 0:
        return ""
    # cut at the next function label at line start
    rest = out[start:]
    lines = rest.splitlines()
    kept = [lines[0]]
    for ln in lines[1:]:
        if re.match(r"^[0-9a-f]+ <[^>]+>:", ln):
            break
        kept.append(ln)
    return "\n".join(kept)


def binary_candidate_pairs(binary):
    data = read_file_bytes(binary)
    resolve = elf_vaddr_to_bytes(data)
    disasm = objdump_main(binary)
    blobs = []   # (vaddr, length)
    imm8 = []    # 8-byte immediates from movabs (possible usernames)

    for ln in disasm.splitlines():
        m = re.search(r"movabs\s+\$0x([0-9a-f]+),", ln)
        if m:
            try:
                imm8.append(int(m.group(1), 16))
            except ValueError:
                pass
        m = re.search(r"lea\s+0x[0-9a-f]+\(%rip\),%r\w+\s+#\s*([0-9a-f]+)",
                      ln)
        if m:
            vaddr = int(m.group(1), 16)
            blobs.append(vaddr)
    # associate lengths: `mov $LEN,%e..` near each blob reference
    lengths = []
    for m in re.finditer(
            r"lea\s+0x[0-9a-f]+\(%rip\),%r\w+\s+#\s*([0-9a-f]+)"
            r"(?:[^\n]*\n){0,6}?.*?mov\s+\$(0x[0-9a-f]+|\d+),%e",
            disasm):
        try:
            lengths.append((int(m.group(1), 16),
                            int(m.group(2), 0)))
        except ValueError:
            pass
    blob_map = {}
    for v, ln_ in lengths:
        blob_map[v] = ln_

    xor_imms = set()
    for m in re.finditer(r"xor\s+\$(0x[0-9a-f]+|\d+),", disasm):
        try:
            xor_imms.add(int(m.group(1), 0) & 0xFF)
        except ValueError:
            pass

    candidates = {}  # bytes -> score

    def add(bs, score):
        if isinstance(bs, int):
            return
        if not looks_like_credential(bs):
            return
        candidates[bytes(bs)] = max(candidates.get(bytes(bs), -1),
                                    score)

    # 8-byte immediates are often an inlined username/password fragment
    for imm in imm8:
        raw = struct.pack("<Q", imm & 0xFFFFFFFFFFFFFFFF)
        add(raw, credential_score(raw) + 3)
        add(raw.rstrip(b"\x00"), credential_score(raw) + 3)

    # blobs referenced by main.main (with known lengths)
    if resolve is not None:
        for vaddr, ln_ in blob_map.items():
            if not (1 <= ln_ <= 128):
                continue
            raw = resolve(vaddr, ln_)
            if raw is None:
                continue
            add(raw, credential_score(raw) + 4)
            for kb in list(xor_imms) + list(range(256)):
                add(decode_single_xor(raw, kb),
                    credential_score(
                        decode_single_xor(raw, kb)) + 1)
        # also try whole blob region without exact length (bounded)
        for vaddr in blobs:
            if vaddr in blob_map:
                continue
            raw = resolve(vaddr, 64)
            if raw is None:
                continue
            for ln_ in (8, 12, 15, 16, 20, 24, 32):
                chunk = raw[:ln_]
                add(chunk, credential_score(chunk))
                for kb in list(xor_imms) + list(range(256)):
                    dec = decode_single_xor(chunk, kb)
                    add(dec, credential_score(dec))

    # generic: printable token scan of the whole binary
    for m in re.finditer(rb"[A-Za-z0-9_@#$\-!+]{4,64}", data):
        tok = m.group(0)
        if looks_like_credential(tok):
            add(tok, credential_score(tok) - 1)

    ordered = sorted(candidates, key=lambda d: -candidates[d])
    ordered = ordered[:60]
    pairs = []
    for i, u in enumerate(ordered):
        for j, p in enumerate(ordered):
            if i != j:
                pairs.append((u, p))
            if len(pairs) > 1500:
                return pairs
    return pairs


# --------------------------------------------------------------------------
# execution
# --------------------------------------------------------------------------

def try_credentials(binary, output, user, password):
    try:
        proc = subprocess.run(
            [binary, "-username", user.decode("latin1"),
             "-password", password.decode("latin1")],
            capture_output=True, timeout=30)
    except Exception as exc:
        print("  exec error for %r: %s" % (user, exc))
        return False
    out = (proc.stdout or b"") + (proc.stderr or b"")
    ok_text = any(m in out for m in SUCCESS_MARKERS)
    ok_file = os.path.isfile(output) and os.path.getsize(output) > 0
    if proc.returncode == 0 and (ok_text or ok_file):
        print("  -> success text: %r" % out[:200])
        return True
    return False


def solve(binary=BINARY, go_files=None, output=OUTPUT):
    if go_files is None:
        go_files = find_go_sources()
    print("Binary: %s" % binary)
    print("Go sources: %s" % (go_files or "none found"))
    pairs = []
    for path in go_files:
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                text = f.read()
        except OSError as exc:
            print("Cannot read %s: %s" % (path, exc))
            continue
        print("Analyzing %s (%d chars)" % (path, len(text)))
        for pair in source_candidate_pairs(text):
            if pair not in pairs:
                pairs.append(pair)
    print("Source-derived pairs: %d" % len(pairs))
    if len(pairs) < 4:
        print("Also analyzing binary for candidates...")
        for pair in binary_candidate_pairs(binary):
            if pair not in pairs:
                pairs.append(pair)
        print("Total pairs: %d" % len(pairs))
    if not pairs:
        print("No credential candidates found.")
        return False
    # fresh check: remove stale output so success is provable
    try:
        if os.path.isfile(output):
            os.remove(output)
            print("Removed stale %s" % output)
    except OSError as exc:
        print("Warning: cannot remove %s: %s" % (output, exc))
    for idx, (u, p) in enumerate(pairs[:2000]):
        print("Try %d: user=%r pass=%r" % (idx + 1, u, p))
        if try_credentials(binary, output, u, p):
            print("Authenticated with user=%r" % u)
            if os.path.isfile(output):
                print("OK: %s generated (%d bytes)"
                      % (output, os.path.getsize(output)))
                return True
            print("Binary accepted creds but %s missing; "
                  "continuing..." % output)
    # final state check (binary may accept last-resort exact pair)
    if os.path.isfile(output) and os.path.getsize(output) > 0:
        print("OK: %s exists." % output)
        return True
    print("FAILED: no candidate pair authenticated.")
    return False


if __name__ == "__main__":
    ok = solve()
    sys.exit(0 if ok else 1)
